CREATE FUNCTION fixture_state(t regclass) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE contents jsonb;
BEGIN
EXECUTE format('SELECT jsonb_build_object(''count'',count(*),''hash'',md5(coalesce(string_agg(to_jsonb(x)::text,'''' ORDER BY id),''''))) FROM %s x',t) INTO contents;
RETURN jsonb_build_object('data',contents,
'owner',(SELECT relowner FROM pg_class WHERE oid=t),
'rls',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity) FROM pg_class WHERE oid=t),
'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY attnum) FROM pg_attribute a WHERE attrelid=t),
'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY oid) FROM pg_constraint c WHERE conrelid=t),
'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY indexrelid) FROM pg_index i WHERE indrelid=t));
END $$;
CREATE TEMP TABLE baseline AS SELECT c.oid, c.relname,fixture_state(c.oid) state,
(SELECT jsonb_agg(to_jsonb(a) ORDER BY grantor,grantee,privilege_type) FROM aclexplode(c.relacl) a) acl,
(SELECT jsonb_agg(to_jsonb(a) ORDER BY grantor,grantee,privilege_type) FROM aclexplode(c.relacl) a WHERE grantee='service_role'::regrole) service_acl
FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND relname IN ('clients','client_contracts','client_invoices','client_invoice_items','client_invoice_item_dates','client_invoice_documents','contractor_credentials','contractor_diver_invoices','contractor_diver_invoice_items','contractor_diver_invoice_documents','contractor_vessel_invoices','contractor_vessel_invoice_items','contractor_vessel_invoice_documents','project_task_code_rates');
