SELECT assert_ok(NOT has_table_privilege('anon','clients',p),'clients anon '||p||' absent') FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p;
SET ROLE anon;
SELECT assert_denied('SELECT * FROM public.clients','clients anon SELECT denied');
SELECT assert_denied('INSERT INTO public.clients VALUES(2,''probe'')','clients anon INSERT denied');
SELECT assert_denied('UPDATE public.clients SET notes=''probe''','clients anon UPDATE denied');
SELECT assert_denied('DELETE FROM public.clients','clients anon DELETE denied');
SELECT assert_denied('TRUNCATE public.clients','clients anon TRUNCATE denied');
SELECT assert_denied('CREATE TABLE public.ref_probe(id integer REFERENCES public.clients(id))','clients anon CREATE denied');
SELECT assert_denied('CREATE TRIGGER probe BEFORE INSERT ON public.clients FOR EACH ROW EXECUTE FUNCTION fixture_trigger()','clients anon CREATE denied');
RESET ROLE;
SELECT assert_ok(NOT has_table_privilege('authenticated','clients',p),'clients authenticated '||p||' absent') FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p;
SET ROLE authenticated;
SELECT assert_denied('SELECT * FROM public.clients','clients authenticated SELECT denied');
SELECT assert_denied('INSERT INTO public.clients VALUES(2,''probe'')','clients authenticated INSERT denied');
SELECT assert_denied('UPDATE public.clients SET notes=''probe''','clients authenticated UPDATE denied');
SELECT assert_denied('DELETE FROM public.clients','clients authenticated DELETE denied');
SELECT assert_denied('TRUNCATE public.clients','clients authenticated TRUNCATE denied');
SELECT assert_denied('CREATE TABLE public.ref_probe(id integer REFERENCES public.clients(id))','clients authenticated CREATE denied');
SELECT assert_denied('CREATE TRIGGER probe BEFORE INSERT ON public.clients FOR EACH ROW EXECUTE FUNCTION fixture_trigger()','clients authenticated CREATE denied');
