SELECT assert_denied('CREATE TRIGGER probe BEFORE INSERT ON public.contractor_vessel_invoices FOR EACH ROW EXECUTE FUNCTION fixture_trigger()','contractor_vessel_invoices authenticated CREATE denied');
RESET ROLE;
SET ROLE service_role;
SELECT assert_ok((SELECT count(*)=1 FROM public.contractor_vessel_invoices),'contractor_vessel_invoices service SELECT');
INSERT INTO public.contractor_vessel_invoices VALUES(2,'service');
UPDATE public.contractor_vessel_invoices SET notes='updated' WHERE id=2;
SELECT assert_ok((SELECT notes='updated' FROM public.contractor_vessel_invoices WHERE id=2),'contractor_vessel_invoices service INSERT/UPDATE');
DELETE FROM public.contractor_vessel_invoices WHERE id=2;
RESET ROLE;
