SELECT assert_ok(service_acl=(SELECT jsonb_agg(to_jsonb(a) ORDER BY grantor,grantee,privilege_type) FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid=baseline.oid AND grantee='service_role'::regrole),relname||' service ACL exact') FROM baseline;
